def set_mosaiq_application_as_context() -> None:
    """Sets the Squish context to the Mosaiq application if it isn't already"""
    if str(AutManager.get_current_app_context) != "accwin":
        AutManager.set_app_context("accwin")

def maximise_mosaiq_window() -> None:
    """Maximises the main Mosaiq application window"""
    CommonActions.maximise_windows_object(MosaiqCoreObjects.mOSAIQ_Main_Window)

def wait_for_main_workspace_area(waitTimeout: int = 20) -> bool:
    """Waits for the main workspace area to load

    :param str waitTimeout: Time to wait in seconds for the workspace area to load
    :return bool: True or False
    """
    return CommonActions.wait_for_object_to_appear(MosaiqCoreObjects.mOSAIQ_Home_Workspace_Tab_Area, waitTimeout)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def wait_for_patient_to_open(waitTimeout: int = 10) -> bool:
    """Waits for any patient to be open
    :param int waitTimeout: Time in seconds to wait for a patient to be open
    :return: True or False
    :rtype: bool
    """
    return CommonActions.wait_for_text_in_object(MosaiqCoreObjects.mOSAQIQ_PatientName_Pane_Area, "MR#", waitTimeout)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def verify_patient_is_open(patientLastName: str) -> bool:
    """Checks that a given patient chart is open using the patients last name

    :param str patientLastName: Last name of patient
    :return: True or False
    :rtype: bool
    """
    toolbar_child_objects = CommonActions.get_child_objects(MosaiqCoreObjects.mOSAQIQ_RightToolbarPanelArea)
    return True if CommonActions.get_child_object_by_object_text(toolbar_child_objects, patientLastName) is not None else False

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_patient_chart_open() -> bool:
    """Checks that any patient chart is open in the dashboard

    :return: True or False
    :rtype: bool
    """
    # is_object_visible(), NOT find_object(): find_object() falls back to returning the first
    # Edit control in the AUT when its target is missing, so "is not None" is true even with no
    # patient open and this could never return False.
    return CommonActions.is_object_visible(MosaiqCoreObjects.toolBar_BarItem_Open_Patient_Label, 2000)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_patient_d_and_i(patientLastName: str) -> None:
    """Checks that a specific patient chart is open and then opens the D and I interface

    :param str patientLastName: Last name of patient
    :return: True or False
    :rtype: bool
    """
    if not verify_patient_is_open(patientLastName):
        raise Exception(f"Patient {patientLastName} is not open")
    CommonActions.left_click_object(MosaiqCoreObjects.toolBar_BarItem_D_and_I)
    CommonActions.find_object(DandI.Main_Window)

