"""Home workspace tabs, keyed by the label shown on the tab."""
HOME_TAB_OBJECT_MAPS = {
    "Work List": MosaiqCoreObjects.tabBar_TabItem_Work_List,
    "QCL": MosaiqCoreObjects.tabBar_TabItem_QCL,
    "Survivorship": MosaiqCoreObjects.tabBar_TabItem_Survivorship,
    "Patient List": MosaiqCoreObjects.tabBar_TabItem_Patient_List,
    "Eligibility": MosaiqCoreObjects.tabBar_TabItem_Eligibility,
    "Links and Mail": MosaiqCoreObjects.tabBar_TabItem_Links_and_Mail,
    "Schedule": MosaiqCoreObjects.tabBar_TabItem_Schedule,
    "LableRx": MosaiqCoreObjects.tabBar_TabItem_LableRx,
    "Patient Work List": MosaiqCoreObjects.tabBar_TabItem_Patient_Work_List,
}

"""Data grid of each Home workspace pane, for panes whose grid has been identified."""
HOME_PANE_DATA_GRID_MAPS = {
    "Work List": MosaiqCoreObjects.homeWorkspace_WorkList_Grid_Data_Panel,
    "Patient List": MosaiqCoreObjects.homeWorkspace_PatientList_Grid_Data_Panel,
}

def get_home_tab_object_map(tabName: str) -> dict:
    """Returns the object map for a Home workspace tab.

    :param str tabName: Tab label, e.g. "Work List" -- see HOME_TAB_OBJECT_MAPS
    :raises ValueError: when the tab label is not mapped
    :return: the tab's object map
    :rtype: dict
    """
    try:
        return HOME_TAB_OBJECT_MAPS[tabName]
    except KeyError:
        raise ValueError(f"Unmapped Home workspace tab '{tabName}'. Mapped tabs: {sorted(HOME_TAB_OBJECT_MAPS)}")

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_home() -> None:
    """Clicks the Home toolbar item to return to the Home workspace.

    Use wait_for_main_workspace_area() afterwards to confirm the workspace loaded.
    """
    CommonActions.left_click_object(MosaiqCoreObjects.toolBar_BarItem_Home)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_home_tab_present(tabName: str, waitTimeout: int = 5) -> bool:
    """Checks that a Home workspace tab is in the tab strip, carries its label and is enabled.

    Deliberately does NOT test the TabItem's `visible` attribute: on these tabs that tracks
    whether the tab's PAGE is the one being displayed, not whether its header is on screen, so
    every unselected tab reports visible=False while sitting plainly in the strip. Testing it
    would just duplicate is_home_tab_selected(). The tab maps match on text, so resolving one
    at all is what proves the header is present and labelled.

    :param str tabName: Tab label, e.g. "Work List"
    :param int waitTimeout: Time in seconds to wait before reporting the tab absent
    :return: True or False
    :rtype: bool
    """
    try:
        tab = CommonActions.wait_for_object_exists(get_home_tab_object_map(tabName), waitTimeout * 1000)
    except Exception:
        return False
    return bool(tab is not None and getattr(tab, "enabled", False))

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_home_tab(tabName: str) -> None:
    """Clicks a Home workspace tab to bring its pane to the front.

    :param str tabName: Tab label, e.g. "Work List"
    """
    CommonActions.left_click_object(get_home_tab_object_map(tabName))

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_home_tab_selected(tabName: str) -> bool:
    """Checks whether a Home workspace tab is the one currently selected.

    Home TabItems report their state through a `selected` attribute, exactly one of which is
    True at a time; a tab that does not expose one is treated as not selected rather than
    assumed active.

    :param str tabName: Tab label, e.g. "Work List"
    :return: True or False
    :rtype: bool
    """
    try:
        tab = CommonActions.wait_for_object_exists(get_home_tab_object_map(tabName), 5000)
    except Exception:
        return False
    return bool(getattr(tab, "selected", False))

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_home_pane_row_count(tabName: str) -> int:
    """Returns the number of data rows in a Home workspace pane's grid.

    Counts the Data Panel only, so column headers (which live in a sibling Header Panel) are
    not mistaken for data.

    :param str tabName: Tab label, e.g. "Work List" -- see HOME_PANE_DATA_GRID_MAPS
    :raises ValueError: when the pane's data grid has not been mapped
    :return: row count, or 0 when the pane's grid holds no rows
    :rtype: int
    """
    try:
        data_panel = HOME_PANE_DATA_GRID_MAPS[tabName]
    except KeyError:
        raise ValueError(f"No data grid mapped for Home workspace pane '{tabName}'. Mapped panes: {sorted(HOME_PANE_DATA_GRID_MAPS)}")
    try:
        return len(CommonActions.get_child_objects(data_panel))
    except Exception:
        return 0

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_chart_for_current_patient() -> None:
    """Opens the Chart interface for whichever patient is currently open.

    Same as open_patient_chart() but keyed off the presence of the open patient toolbar label
    rather than a last name the caller has to know up front. Use this when the patient was
    opened by MR number.

    :raises Exception: when no patient chart is currently open
    """
    if not is_patient_chart_open():
        raise Exception("No patient is currently open")
    CommonActions.left_click_object(MosaiqCoreObjects.toolBar_BarItem_Chart)

