@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def wait_for_patient_chart_to_close(waitTimeout: int = 15) -> bool:
    """Waits for the open patient label to go away from the dashboard, i.e. for no patient to be open

    :param int waitTimeout: Time in seconds to wait for the chart to close
    :return: True or False
    :rtype: bool
    """
    # Polls is_patient_chart_open() rather than wait_for_object_to_disappear(): the latter keys
    # off squishtest.object.exists(), and the open patient label survives in the object tree
    # after the chart closes, so it never reports the object as gone.
    deadline = time.time() + waitTimeout
    while True:
        if not is_patient_chart_open():
            return True
        if time.time() >= deadline:
            return False
        time.sleep(1)

