@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_file_recentpatient(n:int):
    """
    Clicks File > Recent Patient N menu option from the File menu.

    param: int n, in [1-5], to tell which one to select

    return: None
    """
    if n > 5 or n < 1:
        raise Exception("n should be in [1,5]")

    obj = MosaiqCoreObjects.file_MenuItem_RecentPatient_One
    if n > 1:
        if n == 2:
            obj = MosaiqCoreObjects.file_MenuItem_RecentPatient_Two
        elif n == 3:
            obj = MosaiqCoreObjects.file_MenuItem_RecentPatient_Three
        elif n == 4:
            obj = MosaiqCoreObjects.file_MenuItem_RecentPatient_Four
        elif n == 5:
            obj = MosaiqCoreObjects.file_MenuItem_RecentPatient_Five

    CommonActions.left_click_object(MosaiqCoreObjects.menuBar_Item_File)
    time.sleep(0.3)
    CommonActions.left_click_object_no_move(obj)

